"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import { Compass, Save, X } from "lucide-react";
import { DispensarNudgeGscAlphaSeo, SalvarRespostasOnboardingAlphaSeo, SalvarSiteOnboardingAlphaSeo } from "@/actions/AlphaSeoOnboarding";
import { SeoCard } from "../shared/PageHeader";

function record(value: unknown): Record<string, unknown> | null { return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : null; }
const FEATURES = ["Keyword Research", "Rank Tracking", "Site Audit", "Backlinks", "Visibilidade em IA", "SAM"];

export function OnboardingPanel({ projectId, data, chatState, domain, gscConnected }: { projectId: string; data: unknown; chatState: unknown; domain: string | null; gscConnected: boolean }) {
  const root = record(data);
  const chat = record(chatState);
  const answers = record(root?.answers);
  const initialFeatures = Array.isArray(answers?.interestedFeatures) ? answers.interestedFeatures.filter((value): value is string => typeof value === "string") : [];
  const [features, setFeatures] = useState(initialFeatures);
  const [nudge, setNudge] = useState(!gscConnected && root?.gscNudgeDismissedAt == null);
  const [message, setMessage] = useState("");
  const [pending, start] = useTransition();
  function saveAnswers(form: FormData) { start(async () => { const result = await SalvarRespostasOnboardingAlphaSeo({ projectId, interestedFeatures: features, workFor: String(form.get("workFor") ?? ""), clientWebsiteCount: String(form.get("clientWebsiteCount") ?? ""), foundVia: String(form.get("foundVia") ?? ""), mcpSetupIntent: form.get("mcpSetupIntent"), completed: true }); setMessage(result.success ? "Preferências de onboarding salvas." : result.error); }); }
  function saveSite(form: FormData) { start(async () => { const result = await SalvarSiteOnboardingAlphaSeo({ projectId, domain: form.get("domain"), locationCode: Number(form.get("locationCode")), locationName: form.get("locationName") || null, languageCode: form.get("languageCode"), market: form.get("market") }); setMessage(result.success ? "Site principal atualizado." : result.error); }); }
  function dismiss() { start(async () => { const result = await DispensarNudgeGscAlphaSeo({ projectId }); if (!result.success) return setMessage(result.error); setNudge(false); }); }
  return <div className="space-y-4">
    {nudge && <div className="flex flex-col gap-3 rounded-2xl border border-sky-400/20 bg-sky-400/[.08] p-4 sm:flex-row sm:items-center"><Compass className="text-sky-300"/><div className="flex-1"><b className="text-sm text-white">Conecte dados próprios do Search Console</b><p className="mt-1 text-xs text-sky-100/70">Use consultas, páginas, países e dispositivos reais no observatório.</p></div><Link href={`/PainelAlpha/AlphaSEO/${projectId}/settings/integrations`} className="inline-flex min-h-11 items-center justify-center rounded-xl bg-sky-300 px-4 text-xs font-black text-sky-950">Conectar GSC</Link><button type="button" onClick={dismiss} aria-label="Dispensar lembrete GSC" className="grid size-11 place-items-center rounded-xl border border-sky-300/20"><X size={14}/></button></div>}
    <SeoCard className="p-5"><details open={root?.completedAt == null}><summary className="cursor-pointer text-sm font-bold text-white">Configure seu primeiro fluxo</summary>{Boolean(chat?.projectId) && <div className="mt-4 flex flex-wrap items-center gap-3 rounded-xl border border-violet-400/15 bg-violet-400/[.06] p-3"><p className="min-w-0 flex-1 text-xs text-violet-100/80">O SAM já pode continuar o onboarding com o contexto de {String(chat?.domain ?? domain ?? "seu projeto")}.</p><Link href={`/PainelAlpha/AlphaSEO/${projectId}/sam`} className="inline-flex min-h-11 items-center rounded-xl border border-violet-300/20 px-3 text-xs font-bold text-violet-200">Continuar no SAM</Link></div>}<div className="mt-5 grid gap-5 xl:grid-cols-2"><form action={saveSite} className="grid gap-3"><h3 className="text-xs font-bold uppercase text-slate-500">Site e mercado</h3><input name="domain" defaultValue={domain ?? ""} required placeholder="site.com.br" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"/><div className="grid grid-cols-2 gap-2"><input name="market" defaultValue="BR" required maxLength={2} aria-label="Mercado" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"/><input name="languageCode" defaultValue="pt" required aria-label="Idioma" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"/></div><div className="grid grid-cols-2 gap-2"><input name="locationCode" type="number" defaultValue={2076} required aria-label="Código de localização" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"/><input name="locationName" placeholder="São Paulo, Brasil" aria-label="Nome da localização" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"/></div><SaveButton pending={pending} label="Salvar site"/></form>
    <form action={saveAnswers} className="grid gap-3"><h3 className="text-xs font-bold uppercase text-slate-500">Como você usará Alpha SEO?</h3><div className="grid grid-cols-2 gap-2">{FEATURES.map((feature) => <label key={feature} className="flex min-h-11 items-center gap-2 rounded-xl border border-white/5 px-3 text-xs text-slate-300"><input type="checkbox" checked={features.includes(feature)} onChange={(event) => setFeatures((rows) => event.target.checked ? [...rows, feature] : rows.filter((row) => row !== feature))}/>{feature}</label>)}</div><input name="workFor" defaultValue={String(answers?.workFor ?? "")} placeholder="Trabalho para minha empresa/agência" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"/><div className="grid grid-cols-2 gap-2"><input name="clientWebsiteCount" defaultValue={String(answers?.clientWebsiteCount ?? "")} placeholder="Quantidade de sites" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"/><input name="foundVia" defaultValue={String(answers?.foundVia ?? "")} placeholder="Como conheceu" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"/></div><select name="mcpSetupIntent" defaultValue={String(answers?.mcpSetupIntent ?? "yes")} className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"><option value="yes">Quero configurar MCP</option><option value="no">MCP mais tarde</option></select><SaveButton pending={pending} label="Concluir onboarding"/></form></div></details>{message && <p role="status" className="mt-4 text-xs text-slate-400">{message}</p>}</SeoCard>
  </div>;
}

function SaveButton({ pending, label }: { pending: boolean; label: string }) { return <button disabled={pending} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-[rgb(var(--seo-accent))] px-4 text-xs font-black text-slate-950"><Save size={13}/>{label}</button>; }
