"use client";

import { useState, useTransition } from "react";
import { Download, Pencil, Plus, RefreshCw, Sheet, Tag, Trash2 } from "lucide-react";
import {
  AprovarCustoMetricasPalavrasChaveAlphaSeo,
  AtualizarMetricasPalavrasChaveAlphaSeo,
  AtualizarTagPalavrasChaveAlphaSeo,
  AtualizarTagsPalavrasChaveAlphaSeo,
  EstimarCustoMetricasPalavrasChaveAlphaSeo,
  ExcluirTagPalavrasChaveAlphaSeo,
  ListarPalavrasChaveSalvasAlphaSeo,
  RemoverPalavrasChaveAlphaSeo,
  SalvarPalavrasChaveAlphaSeo,
} from "@/actions/AlphaSeoSavedKeywords";
import { ExportarCsvAlphaSeo, ExportarGoogleSheetsAlphaSeo } from "@/actions/AlphaSeoExports";
import { SeoCard, StatePanel } from "../shared/PageHeader";

type TagRow = { id: string; name: string; color: string | null; keywordCount: number };
type Row = { id: string; keyword: string; locationCode: number; languageCode: string; searchVolume: number | null; cpc: number | null; keywordDifficulty: number | null; intent: string | null; tags: TagRow[] };
type PageData = { rows: Row[]; tags: TagRow[]; pagination: { page: number; limit: 50 | 100 | 250; total: number; totalPages: number } };
type Filters = { search: string; include: string; exclude: string; minVolume: string; maxVolume: string; minCpc: string; maxCpc: string; minDifficulty: string; maxDifficulty: string; tagIds: string[]; sort: "createdAt" | "keyword"; order: "asc" | "desc"; limit: 50 | 100 | 250 };
type MetricsEstimate = { requestHash: string; units: number; estimatedMicrosUsd: number; approvalRequired: boolean };

const columns = [{ key: "keyword", label: "Keyword" }, { key: "searchVolume", label: "Volume" }, { key: "cpc", label: "CPC" }, { key: "keywordDifficulty", label: "KD" }, { key: "intent", label: "Intenção" }, { key: "tags", label: "Tags" }];
const emptyFilters: Filters = { search: "", include: "", exclude: "", minVolume: "", maxVolume: "", minCpc: "", maxCpc: "", minDifficulty: "", maxDifficulty: "", tagIds: [], sort: "createdAt", order: "desc", limit: 50 };

function object(value: unknown): Record<string, unknown> | null { return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : null; }
function tagRows(value: unknown): TagRow[] { if (!Array.isArray(value)) return []; return value.flatMap((item) => { const row = object(item); return row && typeof row.id === "string" && typeof row.name === "string" ? [{ id: row.id, name: row.name, color: typeof row.color === "string" ? row.color : null, keywordCount: typeof row.keywordCount === "number" ? row.keywordCount : 0 }] : []; }); }
function parse(value: unknown): PageData { const root = object(value); const pagination = object(root?.pagination); const rows = Array.isArray(root?.rows) ? root.rows.flatMap((item) => { const row = object(item); if (!row || typeof row.id !== "string" || typeof row.keyword !== "string") return []; return [{ id: row.id, keyword: row.keyword, locationCode: Number(row.locationCode), languageCode: String(row.languageCode), searchVolume: typeof row.searchVolume === "number" ? row.searchVolume : null, cpc: typeof row.cpc === "number" ? row.cpc : null, keywordDifficulty: typeof row.keywordDifficulty === "number" ? row.keywordDifficulty : null, intent: typeof row.intent === "string" ? row.intent : null, tags: tagRows(row.tags) }]; }) : []; return { rows, tags: tagRows(root?.tags), pagination: { page: Number(pagination?.page ?? 1), limit: [50, 100, 250].includes(Number(pagination?.limit)) ? Number(pagination?.limit) as 50 | 100 | 250 : 50, total: Number(pagination?.total ?? rows.length), totalPages: Number(pagination?.totalPages ?? (rows.length ? 1 : 0)) } }; }
function optionalNumber(value: string) { return value.trim() ? Number(value) : undefined; }
function terms(value: string) { return value.split(",").map((item) => item.trim()).filter(Boolean); }

export function SavedKeywordsTable({ projectId, initialData }: { projectId: string; initialData: unknown }) {
  const initial = parse(initialData);
  const [data, setData] = useState(initial);
  const [filters, setFilters] = useState(emptyFilters);
  const [selected, setSelected] = useState<string[]>([]);
  const [entry, setEntry] = useState("");
  const [tagName, setTagName] = useState("");
  const [tagColor, setTagColor] = useState("");
  const [selectedTagId, setSelectedTagId] = useState("");
  const [message, setMessage] = useState("");
  const [metricsEstimate, setMetricsEstimate] = useState<MetricsEstimate | null>(null);
  const [pending, start] = useTransition();
  const chosen = data.rows.filter((row) => selected.includes(row.id));

  function input(page: number, limit = filters.limit) { return { projectId, search: filters.search || undefined, includeTerms: terms(filters.include), excludeTerms: terms(filters.exclude), minVolume: optionalNumber(filters.minVolume), maxVolume: optionalNumber(filters.maxVolume), minCpc: optionalNumber(filters.minCpc), maxCpc: optionalNumber(filters.maxCpc), minDifficulty: optionalNumber(filters.minDifficulty), maxDifficulty: optionalNumber(filters.maxDifficulty), tagIds: filters.tagIds, sort: filters.sort, order: filters.order, page, limit }; }
  async function fetchPage(page: number, limit = filters.limit) { const result = await ListarPalavrasChaveSalvasAlphaSeo(input(page, limit)); if (!result.success) throw new Error(result.error); return parse(result.data); }
  function load(page = 1) { start(async () => { try { const next = await fetchPage(page); setData(next); setSelected([]); setMessage(`${next.pagination.total} keywords encontradas.`); } catch (error) { setMessage(error instanceof Error ? error.message : "Falha ao listar keywords."); } }); }
  function add() { const keywords = entry.split(/[\n,]/).map((value) => value.trim()).filter(Boolean); if (!keywords.length) return; start(async () => { const result = await SalvarPalavrasChaveAlphaSeo({ projectId, keywords, tags: [], tagMode: "append", metrics: [] }); if (!result.success) return setMessage(result.error); setEntry(""); setData(await fetchPage(1)); setMessage(`${keywords.length} keywords salvas.`); }); }
  function remove() { if (!selected.length) return; start(async () => { const result = await RemoverPalavrasChaveAlphaSeo({ projectId, savedKeywordIds: selected }); if (!result.success) return setMessage(result.error); setData(await fetchPage(data.pagination.page)); setSelected([]); setMessage("Keywords removidas."); }); }
  function applyTag() { if (!selected.length || !tagName.trim()) return; start(async () => { const result = await AtualizarTagsPalavrasChaveAlphaSeo({ projectId, savedKeywordIds: selected, addTags: [tagName], removeTagIds: [] }); if (!result.success) return setMessage(result.error); setTagName(""); setData(await fetchPage(data.pagination.page)); setMessage("Tag aplicada."); }); }
  function removeTagAssignments() { if (!selected.length || !selectedTagId) return; start(async () => { const result = await AtualizarTagsPalavrasChaveAlphaSeo({ projectId, savedKeywordIds: selected, addTags: [], removeTagIds: [selectedTagId] }); if (!result.success) return setMessage(result.error); setData(await fetchPage(data.pagination.page)); setMessage("Tag removida das keywords selecionadas."); }); }
  function editTag() { if (!selectedTagId || !tagName.trim()) return; start(async () => { const result = await AtualizarTagPalavrasChaveAlphaSeo({ projectId, tagId: selectedTagId, name: tagName, color: tagColor || null }); if (!result.success) return setMessage(result.error); setData(await fetchPage(data.pagination.page)); setMessage("Tag atualizada."); }); }
  function deleteTag() { if (!selectedTagId || !window.confirm("Excluir esta tag e todas as suas associações?")) return; start(async () => { const result = await ExcluirTagPalavrasChaveAlphaSeo({ projectId, tagId: selectedTagId, force: true }); if (!result.success) return setMessage(result.error); setSelectedTagId(""); setTagName(""); setTagColor(""); setData(await fetchPage(data.pagination.page)); setMessage("Tag excluída."); }); }
  function estimateRefresh() { start(async () => { const result = await EstimarCustoMetricasPalavrasChaveAlphaSeo({ projectId, savedKeywordIds: selected.length ? selected : undefined }); if (!result.success) return setMessage(result.error); setMetricsEstimate(result.data as MetricsEstimate); setMessage("Estimativa calculada no servidor."); }); }
  function refresh() { if (!metricsEstimate) return; start(async () => { const request = { projectId, savedKeywordIds: selected.length ? selected : undefined }; if (metricsEstimate.approvalRequired) { const approval = await AprovarCustoMetricasPalavrasChaveAlphaSeo({ ...request, requestHash: metricsEstimate.requestHash }); if (!approval.success) return setMessage(approval.error); } const result = await AtualizarMetricasPalavrasChaveAlphaSeo(request); if (!result.success) return setMessage(result.error); setMetricsEstimate(null); setData(await fetchPage(data.pagination.page)); setMessage("Métricas atualizadas."); }); }
  async function allFilteredRows() { if (chosen.length) return chosen; const first = await fetchPage(1, 250); const all = [...first.rows]; for (let page = 2; page <= first.pagination.totalPages; page += 1) all.push(...(await fetchPage(page, 250)).rows); return all; }
  function exportRows(format: "csv" | "sheets") { start(async () => { try { const rows = (await allFilteredRows()).map((row) => ({ ...row, tags: row.tags.map((tag) => tag.name).join(", ") })); const exportInput = { projectId, kind: "SAVED_KEYWORDS", rows, columns, title: "Alpha SEO — Keywords salvas" }; const result = format === "csv" ? await ExportarCsvAlphaSeo(exportInput) : await ExportarGoogleSheetsAlphaSeo(exportInput); if (!result.success) return setMessage(result.error); const out = result.data as { content?: string; filename?: string; clipboardText?: string; spreadsheetUrl?: string }; if (format === "csv" && out.content) { const url = URL.createObjectURL(new Blob([out.content], { type: "text/csv;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = out.filename ?? "keywords.csv"; anchor.click(); URL.revokeObjectURL(url); } else if (out.clipboardText && out.spreadsheetUrl) { await navigator.clipboard.writeText(out.clipboardText); window.open(out.spreadsheetUrl, "_blank", "noopener,noreferrer"); } setMessage(format === "csv" ? "CSV filtrado gerado." : "Dados filtrados copiados para o Google Sheets."); } catch (error) { setMessage(error instanceof Error ? error.message : "Falha ao exportar."); } }); }

  return <div className="space-y-4">
    <SeoCard className="p-4"><div className="grid gap-3 lg:grid-cols-[1fr_auto]"><textarea value={entry} onChange={(event) => setEntry(event.target.value)} rows={2} placeholder="Adicionar keywords, uma por linha" className="rounded-xl border border-white/10 bg-slate-950/70 p-3 text-sm outline-none"/><button type="button" onClick={add} disabled={pending || !entry.trim()} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-[rgb(var(--seo-accent))] px-4 text-sm font-black text-slate-950"><Plus size={15}/>Salvar</button></div></SeoCard>
    <SeoCard className="p-4"><div className="grid gap-3 md:grid-cols-3 xl:grid-cols-5"><input value={filters.search} onChange={(event) => setFilters((old) => ({ ...old, search: event.target.value }))} placeholder="Buscar keyword" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-xs"/><input value={filters.include} onChange={(event) => setFilters((old) => ({ ...old, include: event.target.value }))} placeholder="Incluir termos (vírgulas)" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-xs"/><input value={filters.exclude} onChange={(event) => setFilters((old) => ({ ...old, exclude: event.target.value }))} placeholder="Excluir termos (vírgulas)" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-xs"/><select value={filters.sort} onChange={(event) => setFilters((old) => ({ ...old, sort: event.target.value as Filters["sort"] }))} className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-xs"><option value="createdAt">Mais recentes</option><option value="keyword">Keyword</option></select><button type="button" onClick={() => load(1)} disabled={pending} className="min-h-11 rounded-xl border border-white/10 px-4 text-xs font-bold">Aplicar filtros</button></div><details className="mt-3"><summary className="cursor-pointer text-xs font-bold text-slate-400">Filtros numéricos e tags</summary><div className="mt-3 grid gap-2 sm:grid-cols-2 xl:grid-cols-4">{(["minVolume", "maxVolume", "minCpc", "maxCpc", "minDifficulty", "maxDifficulty"] as const).map((key) => <input key={key} type="number" min={0} value={filters[key]} onChange={(event) => setFilters((old) => ({ ...old, [key]: event.target.value }))} placeholder={key} className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-xs"/>)}<select multiple value={filters.tagIds} onChange={(event) => setFilters((old) => ({ ...old, tagIds: Array.from(event.target.selectedOptions, (option) => option.value) }))} aria-label="Filtrar tags" className="min-h-24 rounded-xl border border-white/10 bg-slate-950 px-3 text-xs">{data.tags.map((tag) => <option key={tag.id} value={tag.id}>{tag.name} ({tag.keywordCount})</option>)}</select><div className="grid grid-cols-2 gap-2"><select value={filters.limit} onChange={(event) => setFilters((old) => ({ ...old, limit: Number(event.target.value) as Filters["limit"] }))} className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-xs"><option value={50}>50/página</option><option value={100}>100/página</option><option value={250}>250/página</option></select><select value={filters.order} onChange={(event) => setFilters((old) => ({ ...old, order: event.target.value as Filters["order"] }))} className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-xs"><option value="desc">Descendente</option><option value="asc">Ascendente</option></select></div></div></details></SeoCard>
    <SeoCard className="p-4"><div className="grid gap-3 xl:grid-cols-[1fr_180px_140px_auto_auto_auto]"><input value={tagName} onChange={(event) => setTagName(event.target.value)} placeholder="Nome da tag" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-xs"/><select value={selectedTagId} onChange={(event) => { const id = event.target.value; const tag = data.tags.find((item) => item.id === id); setSelectedTagId(id); setTagName(tag?.name ?? ""); setTagColor(tag?.color ?? ""); }} className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-xs"><option value="">Gerenciar tag</option>{data.tags.map((tag) => <option key={tag.id} value={tag.id}>{tag.name} ({tag.keywordCount})</option>)}</select><input value={tagColor} onChange={(event) => setTagColor(event.target.value)} placeholder="Cor (#hex)" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-xs"/><Tool icon={Tag} label="Aplicar" onClick={applyTag}/><Tool icon={Pencil} label="Renomear" onClick={editTag}/><Tool icon={Trash2} label="Excluir tag" onClick={deleteTag} danger/></div><button type="button" onClick={removeTagAssignments} disabled={!selected.length || !selectedTagId} className="mt-2 min-h-11 rounded-xl border border-white/10 px-3 text-xs font-bold text-slate-300">Remover tag das selecionadas</button></SeoCard>
    {data.rows.length ? <><SeoCard className="flex flex-wrap items-center gap-2 p-3"><Tool icon={RefreshCw} label="Estimar métricas" onClick={estimateRefresh}/><Tool icon={Download} label="CSV filtrado" onClick={() => exportRows("csv")}/><Tool icon={Sheet} label="Sheets filtrado" onClick={() => exportRows("sheets")}/><Tool icon={Trash2} label="Remover keywords" onClick={remove} danger/><span className="ml-auto text-xs text-slate-500">{selected.length} selecionadas · {data.pagination.total} resultados</span></SeoCard>{metricsEstimate && <SeoCard className="flex flex-wrap items-center justify-between gap-3 border-amber-400/20 p-4"><span className="text-xs text-amber-100">{metricsEstimate.units} keywords · até US$ {(metricsEstimate.estimatedMicrosUsd / 1_000_000).toFixed(4)}{metricsEstimate.approvalRequired ? " · aprovação obrigatória" : ""}</span><button type="button" onClick={refresh} disabled={pending} className="min-h-11 rounded-xl bg-amber-300 px-4 text-xs font-black text-amber-950">{metricsEstimate.approvalRequired ? "Aprovar e atualizar" : "Atualizar métricas"}</button></SeoCard>}<SeoCard className="overflow-x-auto"><table className="w-full min-w-[900px] text-left text-sm"><thead className="border-b border-white/5 text-[10px] uppercase text-slate-500"><tr><th className="p-4"><input type="checkbox" checked={selected.length === data.rows.length} onChange={(event) => { setSelected(event.target.checked ? data.rows.map((row) => row.id) : []); setMetricsEstimate(null); }}/></th><th className="p-4">Keyword</th><th className="p-4">Mercado</th><th className="p-4">Volume</th><th className="p-4">CPC</th><th className="p-4">KD</th><th className="p-4">Intenção</th><th className="p-4">Tags</th></tr></thead><tbody>{data.rows.map((row) => <tr key={row.id} className="border-b border-white/[.04]"><td className="p-4"><input type="checkbox" checked={selected.includes(row.id)} onChange={(event) => { setSelected((ids) => event.target.checked ? [...ids, row.id] : ids.filter((id) => id !== row.id)); setMetricsEstimate(null); }}/></td><td className="p-4 font-medium text-white">{row.keyword}</td><td className="p-4 text-slate-400">{row.locationCode} · {row.languageCode}</td><td className="p-4 tabular-nums text-slate-300">{row.searchVolume ?? "—"}</td><td className="p-4 tabular-nums text-slate-300">{row.cpc ?? "—"}</td><td className="p-4 tabular-nums text-slate-300">{row.keywordDifficulty ?? "—"}</td><td className="p-4 text-slate-400">{row.intent ?? "—"}</td><td className="p-4 text-slate-500">{row.tags.map((tag) => tag.name).join(", ") || "—"}</td></tr>)}</tbody></table></SeoCard><div className="flex items-center justify-between"><button type="button" onClick={() => load(data.pagination.page - 1)} disabled={pending || data.pagination.page <= 1} className="min-h-11 rounded-xl border border-white/10 px-4 text-xs font-bold">Anterior</button><span className="text-xs text-slate-500">Página {data.pagination.page} de {Math.max(1, data.pagination.totalPages)}</span><button type="button" onClick={() => load(data.pagination.page + 1)} disabled={pending || data.pagination.page >= data.pagination.totalPages} className="min-h-11 rounded-xl border border-white/10 px-4 text-xs font-bold">Próxima</button></div></> : <StatePanel title="Nenhuma keyword salva" description="Adicione termos manualmente ou ajuste os filtros."/>}
    {message && <p role="status" className="text-sm text-slate-400">{message}</p>}
  </div>;
}

function Tool({ icon: Icon, label, onClick, danger = false }: { icon: typeof Tag; label: string; onClick: () => void; danger?: boolean }) { return <button type="button" onClick={onClick} className={`inline-flex min-h-11 items-center justify-center gap-2 rounded-lg border px-3 text-xs font-bold ${danger ? "border-rose-400/20 text-rose-300" : "border-white/10 text-slate-300"}`}><Icon size={13}/>{label}</button>; }
